function RBGlazyStripeReference() {
  try {
    const session = JSON.parse(window.localStorage.getItem('glazy-session') || 'null');
    const id = String(session?.user?.id || '');
    if (Date.parse(session?.expires) > Date.now() && /^[1-9]\d{0,15}$/.test(id)) return 'glazy_' + id;
  } catch (_) {}
  return '';
}
function RBGlazyStripeLink(href) {
  const reference = RBGlazyStripeReference();
  if (!reference) return href;
  const url = new URL(href);
  url.searchParams.set('client_reference_id', reference);
  return url.href;
}
function RBGlazyStripeButton(button) {
  const reference = RBGlazyStripeReference();
  if (reference) button.setAttribute('client-reference-id', reference);
}
function RBGlazyStripeFrameHTML(html) {
  const reference = RBGlazyStripeReference();
  return reference ? html.replace('<stripe-buy-button ', '<stripe-buy-button client-reference-id="' + reference + '" ') : html;
}
function RBGlazyStripeSupportLink(area) {
  const link = area.querySelector('a[href^="https://donate.stripe.com/"]');
  if (link) {
    const url = new URL(link.href);
    url.searchParams.delete('client_reference_id');
    link.href = RBGlazyStripeLink(url.href);
  }
}
function RBGlazyStripeClone(template) {
  const content = template.content.cloneNode(true);
  const frame = content.querySelector('iframe');
  frame.srcdoc = RBGlazyStripeFrameHTML(frame.srcdoc);
  return content;
}
